  entry=positions.map(p=>({...p}));accidentalTimers={};facings=ROLES.map(()=>-Math.PI/2);$('scene-result').hidden=true;stats.last=currentChapter().id;stats.role=run.role;stats.branch=run.branch;persist();updateHash();updateUI();renderArena();
