function rebuild({role=run.role,branch=run.branch,seed=run.seed}={}){const id=currentChapter()?.id;run=createRun({role,branch,seed});passed.clear();attemptStarted=false;load(Math.max(0,run.chapters.findIndex(c=>c.id===id)));}
