  $('scene-description').textContent=s.body;$('chapter-tips').innerHTML=c.tips.map(t=>`<li>${t}</li>`).join('');$('seed-label').textContent=`本局種子 ${run.seed} · ${c.time===null?'階段教學':`${timeLabel(c.time)} 階段事件參考`}`;const source=$('chapter-source');source.href=raidId==='m5s'||raidId==='top'?c.source:'high-concept.html';source.textContent=raidId==='m5s'?'XivStrat・本機制圖文 ↗':raidId==='top'?'莫古力原攻略・本階段 ↗':'原版概念支配 I 專練 ↗';source.target=raidId==='top'||raidId==='m5s'?'_blank':'_self';
  $('cast-title').textContent=s.name;$('attempt-count').textContent=stats.attempts;$('clear-count').textContent=stats.clears;
  $('play').textContent=state==='running'?demo?'示範中…':$('mode').value==='challenge'?'限時挑戰中…':'✓ 結算本步':state==='paused'?'▶ 繼續練習':state==='failed'||state==='review'?'↻ 重試本步':state==='cleared'?'↻ 再練本章':'▶ 開始練習';$('play').disabled=state==='running'&&(demo||$('mode').value==='challenge');$('pause').disabled=!['running','paused'].includes(state);$('pause').textContent=state==='paused'?'▶':'Ⅱ';$('demo').textContent=demo&&['running','paused'].includes(state)?'□ 停止示範':'▷ 自動示範';
  $('role-picker').innerHTML=ROLES.map(role=>`<button data-role="${role}" class="${role===run.role?'selected':''}" aria-pressed="${role===run.role}">${role}</button>`).join('');
