    out+=(s.waymarks||[]).map(w=>`<g><${/\d/.test(w.label)?'rect':'circle'} ${/\d/.test(w.label)?`x="${w.x-2.3}" y="${w.y-2.3}" width="4.6" height="4.6"`:`cx="${w.x}" cy="${w.y}" r="2.5"`} fill="${w.color}" fill-opacity=".15" stroke="${w.color}" stroke-width=".4"/><text x="${w.x}" y="${w.y+1}" text-anchor="middle" fill="${w.color}" font-size="2.8">${w.label}</text></g>`).join('');
    out+=(s.spotlights||[]).map(w=>`<g><circle cx="${w.x}" cy="${w.y}" r="${w.r}" fill="#f5e2a1" fill-opacity=".28" stroke="#ffe9ae" stroke-width=".55"/><text x="${w.x}" y="${w.y-5.2}" text-anchor="middle" fill="#ffe9ae" font-size="2.2">燈 ${ROLES[w.player]}</text></g>`).join('');
    out+='<g clip-path="url(#floor-clip)">'+[...(s.coneBaits||[]),...(s.roleCones||[])].map(b=>{const p=positions[b.player],a=Math.atan2(p.y-b.origin.y,p.x-b.origin.x);return shape({kind:'cone',...b.origin,angle:a,width:b.width,r:150},'#be9fe1',.13);}).join('')+'</g>';
